          <span :class="item.label===$t('yqhy.yqhy03')?'num':''">{{ item.value }}</span>
          <div v-show="item.showCopyBtn" class="copy_btn" @click="doCopy(item.value,index)">{{ $t('yqhy.yqhy06') }}</div>
