        <img :src="item.icon" alt=""></div>
      </div>
      <div class="split-line" />
      <div class="analyze">
        <div class="left">
          <div class="value">{{ value1 }}</div>
          <div class="label">{{ $t('yqhy.yqhy08') }}</div>
