<script>
import TitleLine from './modules/TitleLine'
import { shareother } from '@/api/user'
import fbIcon from '@/assets/portal/auth/图标_fb.svg'
import googleIcon from '@/assets/portal/auth/图标_google.svg'
import tgIcon from '@/assets/portal/auth/图标_tg.svg'
export default {
  components: {
    TitleLine
  },
  props: {
    // currentValue: {
    //   type: Number,
    //   default: 0
    // }
  },
  data() {
    return {
      loginTypeList:[
        {icon:tgIcon,label:'tg'},{icon:fbIcon,label:'fb'},{icon:googleIcon,label:'google'}
      ],
      telauourl:'',
      backs:'',
      title: this.$t('yqhy.yqhy13'),
      value1: '',
      value2: '',
      showList: [{ label: this.$t('yqhy.yqhy01'), value: '', showCopyBtn: true, showCopySuccess: false }, { label: this.$t('yqhy.yqhy02'), value: '', showCopyBtn: true, showCopySuccess: false }, { label: this.$t('yqhy.yqhy03'), value: '', showCopyBtn: true, showCopySuccess: false }]
    }
  },
  created() {
    shareother().then(async res => {
      this.backs = res.maxdownback
      this.showList[1].value = res.shareurl
      this.showList[0].value = res.telurl
      this.showList[2].value = res.ucode
      this.value1 = res.todayaddnum
      this.value2 = res.undernums
      this.telauourl=res.telauourl
    })
  },
  mounted() {
    // if (localStorage.getItem('currentIndex')) {
    //   this.currentIndex = Number(localStorage.getItem('currentIndex'))
    // }
  },
  methods: {
    goOtherLogin(type){
      if(type === 'tg'){
        // getBotinfo().then(res => {
          window.open(this.telauourl)
        // })
        // this.to('/auth/loginByTg')
      }else {
        this.$toast.fail('敬请期待')
      }
    },
    doCopy(val, index) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
          this.showList[index].showCopyBtn = false
          this.showList[index].showCopySuccess = true
          setTimeout(() => {
            this.showList[index].showCopySuccess = false
            this.showList[index].showCopyBtn = true
          }, 2000)
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }
    // getSubClass(value, label) {
    //   this.currentIndex = value
    //   localStorage.setItem('currentIndex', value)
    // }
  }
}
</script>
